//! Reader for the baseline oracle `fixtures/object-text-layout-record/oracle.txt`
//! (generated by running the verbatim `buildVectorTextGroup`, `serP` and the
//! `desP` text restore of fbe4b8a3; see HANDOFF.md) plus the stub font catalog
//! built from its FACE rows, the same stub faces as the L06-A oracle.
use crate::object_document::object_text_layout_kernels::object_text_layout_kernel::layout_text;
use crate::object_document::object_text_layout_kernels::object_text_layout_kernel::model::{
    FontAdvancePort, FontCatalogPort, LaidOutText,
};
use serde_json::Value;
use std::collections::HashMap;

pub(crate) const ORACLE: &str = include_str!("fixtures/object-text-layout-record/oracle.txt");

/// The smallest valid record: only the required members.
pub(crate) const MINIMAL: &str = r##"{"text":"Hi","font":{"kind":"bundled","fontKey":"Roboto-Regular"},"size":48,"color":"#112233","align":"left","anchorTopLeft":{"x":10,"y":20}}"##;
/// Every member present, with an asset font.
pub(crate) const FULL: &str = r##"{"text":"Hello\nworld","font":{"kind":"asset","assetId":"font-1"},"size":17.5,"color":"#ff00aa80","align":"center","fixedWidth":300,"fixedHeight":null,"bold":true,"italic":false,"underline":true,"strike":false,"letterSpacing":-2.5,"wordSpacing":0,"lineHeightMult":1.25,"textCase":"upper","anchorTopLeft":{"x":-12.75,"y":104.5}}"##;

pub(crate) fn minimal() -> Value {
    serde_json::from_str(MINIMAL).expect("minimal json")
}

/// MINIMAL with one top-level member set (or replaced).
pub(crate) fn with(member: &str, value: Value) -> String {
    let mut record = minimal();
    record[member] = value;
    record.to_string()
}

pub(crate) struct Face {
    upm: f64,
    advances: HashMap<u16, f64>,
}

impl FontAdvancePort for Face {
    fn units_per_em(&self) -> f64 {
        self.upm
    }
    fn advance_units(&self, utf16_unit: u16) -> Option<f64> {
        self.advances.get(&utf16_unit).copied()
    }
}

pub(crate) struct Catalog {
    faces: HashMap<String, Face>,
}

impl FontCatalogPort for Catalog {
    fn knows_key(&self, key: &str) -> bool {
        self.faces.contains_key(key)
    }
    fn face(&self, key: &str) -> Option<&dyn FontAdvancePort> {
        self.faces.get(key).map(|face| face as &dyn FontAdvancePort)
    }
}

/// `(kind, json)` of every data row: FACE, FONTS, KEYS, CASE.
pub(crate) fn rows(kind: &str) -> Vec<Value> {
    ORACLE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| {
            let (tag, rest) = line.split_once(' ').expect("oracle row has a tag");
            (tag == kind).then(|| serde_json::from_str(rest).expect("oracle row is JSON"))
        })
        .collect()
}

pub(crate) fn cases() -> Vec<Value> {
    rows("CASE")
}

pub(crate) fn case(name: &str) -> Value {
    cases()
        .into_iter()
        .find(|row| row["name"] == name)
        .unwrap_or_else(|| panic!("oracle case {name}"))
}

/// Cases the baseline built and the record admits (a root exists and it is not
/// one of the refused roots).
pub(crate) fn admitted_cases() -> Vec<Value> {
    cases()
        .into_iter()
        .filter(|row| row["noRoot"] != true && row["refused"] != true)
        .collect()
}

pub(crate) fn catalog() -> Catalog {
    let faces = rows("FACE")
        .iter()
        .map(|face| {
            let advances = face["advances"]
                .as_object()
                .expect("advances")
                .iter()
                .map(|(unit, advance)| {
                    (
                        unit.parse::<u16>().expect("unit"),
                        advance.as_f64().expect("advance"),
                    )
                })
                .collect();
            let upm = face["upm"].as_f64().expect("upm");
            (
                face["key"].as_str().expect("key").to_string(),
                Face { upm, advances },
            )
        })
        .collect();
    Catalog { faces }
}

/// The layout the native kernel produces for an oracle case's captured record.
pub(crate) fn layout_of(row: &Value, holder: &str) -> LaidOutText {
    let record = super::TextBlockRecord::capture_root_data(&row["rootData"]).expect("admitted");
    let catalog = catalog();
    layout_text(&record.layout_request(holder), Some(&catalog)).expect("layout")
}

/// The baseline glyph tuple list of a case: `[unit, x, y, size, charIndex, wordIndex, lineIndex]`.
pub(crate) fn baseline_glyphs(row: &Value) -> Vec<[f64; 7]> {
    row["layout"]["glyphs"]
        .as_array()
        .expect("glyphs")
        .iter()
        .map(|g| {
            let mut tuple = [0.0; 7];
            for (slot, value) in tuple.iter_mut().zip(g.as_array().expect("glyph").iter()) {
                *slot = value.as_f64().expect("glyph number");
            }
            tuple
        })
        .collect()
}

/// The same tuple read from the native layout, flattened in layout order.
pub(crate) fn native_glyphs(layout: &LaidOutText) -> Vec<[f64; 7]> {
    layout
        .lines
        .iter()
        .flat_map(|line| line.glyphs.iter())
        .map(|g| {
            [
                f64::from(g.unit),
                g.origin_x,
                g.baseline_y,
                g.size,
                g.ordinal as f64,
                g.word_index as f64,
                g.line_index as f64,
            ]
        })
        .collect()
}
